// Turns a Telegram update (typed message OR button tap) into one simple shape,
// and checks that it comes from the owner's chat. Other chats are ignored.
const OWNER_CHAT_ID = '8945018506';
const u = $input.first().json;
let chatId = '', input = '', isButton = false, queryId = '';
if (u.callback_query) {
  isButton = true;
  queryId = String(u.callback_query.id || '');
  chatId = String(u.callback_query.message?.chat?.id || '');
  input = String(u.callback_query.data || '');
} else if (u.message) {
  chatId = String(u.message.chat?.id || '');
  input = String(u.message.text || '');
}
input = input.trim();
// Idempotency: Telegram re-sends an update if our reply is slow. Remember recent update_ids
// so the same update never produces a second reply (manual test runs have no update_id).
const seen = $getWorkflowStaticData('global');
seen.seenUpdates = seen.seenUpdates || [];
let duplicate = false;
if (u.update_id) {
  duplicate = seen.seenUpdates.includes(u.update_id);
  if (!duplicate) { seen.seenUpdates.push(u.update_id); seen.seenUpdates = seen.seenUpdates.slice(-200); }
}
return [{ json: { chatId, input, isButton, queryId, authorized: chatId === OWNER_CHAT_ID && input.length > 0 && !duplicate, duplicate } }];

// Decides what the user asked for, updates the remembered demo state (chosen student,
// chosen posting, recruiter settings, applications), and prepares the input for the engine
// workflow that must run next: 02 (matching), 06 (AI advice), 09 (live jobs) or 10 (recruiter ranking).
const u = $('Normalize Update').first().json;
const cat = $input.first().json;
if (cat.allSynthetic !== true || !Array.isArray(cat.personas) || !Array.isArray(cat.jobs)) {
  throw new Error('Demo catalogue unavailable or invalid');
}
const store = $getWorkflowStaticData('global');
const DEFAULT = { weights: { skills: 40, experience: 30, education: 30 }, threshold: 70 };
const copy = o => JSON.parse(JSON.stringify(o));
store.persona = store.persona || 'alex';
store.posting = store.posting || cat.recruiterPostings[0];
store.settings = store.settings || {};
store.applications = store.applications || {};
store.notified = store.notified || {};

const personas = Object.fromEntries(cat.personas.map(p => [p.id, p]));
const jobById = Object.fromEntries(cat.jobs.map(j => [j.id, j]));
const typed = { '/start': 'home', '/help': 'home', '/menu': 'home', '/candidate': 'c:menu', '/recruiter': 'r:dash',
  '/matches': 'cm', '/match': 'cm', '/live': 'cl', '/notify': 'rn', '/profile': 'cpro', '/browse': 'cb', '/jobs': 'cb', '/advice': 'ci', '/reset': 'demo:reset', '/drill': 'drill' };
const parts = u.input.split(/\s+/);
const first = parts[0].split('@')[0];
let action = first.startsWith('/') ? (typed[first.toLowerCase()] || 'unknown') : first;
const args = parts.slice(1);
const idx = action.indexOf(':');
const verb = idx >= 0 ? action.slice(0, idx) : action;
const arg = idx >= 0 ? action.slice(idx + 1) : '';
const out = { verb, arg, engine: 'none', note: null, error: null };

const settingsOf = id => copy(store.settings[id] || DEFAULT);
const applyPreset = (id, p) => {
  const s = settingsOf(id);
  if (p === 's') s.weights = { skills: 60, experience: 20, education: 20 };
  else if (p === 'e') s.weights = { skills: 20, experience: 60, education: 20 };
  else if (p === 'b') s.weights = { skills: 34, experience: 33, education: 33 };
  else if (p === 't+') s.threshold = Math.min(100, s.threshold + 10);
  else if (p === 't-') s.threshold = Math.max(0, s.threshold - 10);
  else if (p === 'r') { store.settings[id] = copy(DEFAULT); store.notified[id] = {}; return 'Settings reset to 40 / 30 / 30, threshold 70. Notification history for this posting cleared.'; }
  else return null;
  store.settings[id] = s;
  return 'Settings updated.';
};
const parseTyped = (id, list) => {
  const alias = { skills: 'skills', skill: 'skills', experience: 'experience', exp: 'experience', education: 'education', edu: 'education', threshold: 'threshold', min: 'threshold' };
  if (list.length === 1 && /^(reset|default)$/i.test(list[0])) return { ok: true, note: applyPreset(id, 'r') };
  const s = settingsOf(id);
  for (const a of list) {
    const m = a.match(/^([a-z]+)[=:](\d{1,3})$/i);
    const key = m && alias[m[1].toLowerCase()];
    if (!key) return { ok: false, msg: 'I did not understand "' + a + '".' };
    const v = Number(m[2]);
    if (v > 100) return { ok: false, msg: 'Values must be between 0 and 100.' };
    if (key === 'threshold') s.threshold = v; else s.weights[key] = v;
  }
  const w = s.weights, sum = w.skills + w.experience + w.education;
  if (sum !== 100) return { ok: false, msg: 'Weights must add up to 100 (now ' + w.skills + ' + ' + w.experience + ' + ' + w.education + ' = ' + sum + ').' };
  store.settings[id] = s;
  return { ok: true, note: 'Settings updated.' };
};
const personaAsCandidate = p => ({ id: p.candidateId, name: p.name, degree: p.degree, skills: p.skills,
  experienceYears: p.experienceYears, location: p.location });
const recruiterInput = id => {
  const s = settingsOf(id);
  const applied = (store.applications[id] || []).filter(pid => personas[pid]).map(pid => {
    const p = personas[pid];
    return { id: 'TG-' + pid, name: p.name.replace('(fictional)', '(fictional, applied via Telegram)'), education: p.degree,
      experienceYears: p.experienceYears, skills: p.skills, viaTelegram: true };
  });
  return { job: { ...jobById[id], weights: s.weights, threshold: s.threshold },
    candidates: cat.applicants[id].concat(applied), allSynthetic: true };
};

switch (verb) {
  case 'home': case 'c': case 'cb': break;
  case 'r':
    if (arg === 'dash') {
      if (args.length) {
        const r = parseTyped(store.posting, args);
        if (!r.ok) { out.verb = 'rerror'; out.error = r.msg; break; }
        out.note = r.note;
      }
      out.verb = 'rdash'; out.engine = 'recruit';
    }
    break;
  case 'demo':
    store.persona = 'alex'; store.posting = cat.recruiterPostings[0];
    store.settings = {}; store.applications = {}; store.notified = {};
    out.verb = 'home'; out.note = 'Demo reset: applications, recruiter settings and notification history cleared.';
    break;
  case 'cp':
    if (personas[arg]) store.persona = arg;
    out.verb = 'cpro';
    break;
  case 'cpro': break;
  case 'cm': case 'cw': case 'ci':
    out.engine = verb === 'ci' ? 'ai' : 'match';
    out.engineInput = { candidate: personaAsCandidate(personas[store.persona]), jobs: cat.jobs, allSynthetic: true, source: 'seeded-demo-api' };
    break;
  case 'ca':
    if (cat.recruiterPostings.includes(arg)) {
      const list = store.applications[arg] = store.applications[arg] || [];
      out.alreadyApplied = list.includes(store.persona);
      if (!out.alreadyApplied) list.push(store.persona);
    } else out.error = 'This employer is not part of the recruiter demo.';
    break;
  case 'drill':
    // Failure drill: deliberately points workflow 09 at a board that does not exist,
    // to show the retry, the error output, the safe reply and the error-workflow alert live.
    out.verb = 'cl'; out.drill = true; out.engine = 'live';
    out.engineInput = { skills: personas[store.persona].skills, simulateFailure: true };
    break;
  case 'cl':
    out.engine = 'live';
    out.engineInput = { skills: personas[store.persona].skills };
    break;
  case 'rp':
    if (cat.recruiterPostings.includes(arg)) store.posting = arg;
    out.verb = 'rdash'; out.engine = 'recruit';
    break;
  case 'rw':
    out.note = applyPreset(store.posting, arg);
    out.verb = 'rdash'; out.engine = 'recruit';
    break;
  case 'rn':
    out.engine = 'recruit';
    break;
  default:
    out.verb = 'home'; out.note = 'Sorry, I did not understand that. Use the buttons below or /help.';
}
if (out.engine === 'recruit') out.engineInput = recruiterInput(store.posting);
out.persona = personas[store.persona];
out.postingId = store.posting;
out.settings = settingsOf(store.posting);
out.applications = copy(store.applications);
out.catalogue = { jobs: cat.jobs, personas: cat.personas, recruiterPostings: cat.recruiterPostings,
  applicantCounts: Object.fromEntries(cat.recruiterPostings.map(id => [id, cat.applicants[id].length])) };
// Engine workflows receive this item as-is, so expose their inputs at the top level.
if (out.engineInput) Object.assign(out, out.engineInput);
return [{ json: out }];

// Builds the Telegram replies as a list of messages. Each message names the button set ("kb")
// it needs; the send loop delivers them one by one, in order.
const plan = $('Plan Action').first().json;
let r = $input.first().json || {};
// If saving (workflow 07) failed, still show the matches from workflow 02.
if (['cm', 'cw'].includes(plan.verb) && !Array.isArray(r.allScored)) {
  try { const m = $('Match Candidate - SELECT 02').first().json; if (Array.isArray(m.allScored)) r = { ...m, persistedRows: 0 }; } catch (e) { /* engine did not run */ }
}
const store = $getWorkflowStaticData('global');
const cat = plan.catalogue;
const P = plan.persona;
const first = n => String(n).replace(/\s*\(fictional[^)]*\)/, '');
const jobById = Object.fromEntries(cat.jobs.map(j => [j.id, j]));
const bar = s => '█'.repeat(Math.round(s / 10)) + '░'.repeat(10 - Math.round(s / 10));
const msgs = [];
const say = (text, kb = 'none', extra = {}) => msgs.push({ kind: 'text', kb, text, ...extra });
const CAND = 'CANDIDATE SIDE', REC = 'RECRUITER SIDE';
const needsLine = j => j.minimumEducation + '+, ' + j.minimumExperienceYears + ' yr, ' + j.requiredSkills.join(', ');
const engineFailed = () => say('That part of the demo is temporarily unavailable. Nothing was changed. Please try again in a moment.',
  plan.verb.startsWith('r') ? 'rec' : 'cand');

const v = plan.verb;
if (plan.note && !v.startsWith('r')) say(plan.note);

if (v === 'home') {
  say('Welcome to BAIT, an internship matching demo.\n\n' +
    'CANDIDATE SIDE: pick a fictional student, see their profile, browse the internships, get explained matches, and apply.\n' +
    'RECRUITER SIDE: pick a job posting, rank its applicants with your own weights, and notify them.\n\n' +
    'Everyone in the demo is fictional. Real public listings appear only under "Real market" and are labelled.', 'role');
} else if (v === 'c') {
  say(CAND + '\nWho are you? (fictional students)\n\n' + cat.personas.map(p =>
    '• ' + first(p.name) + ': ' + p.degree + ' in ' + p.field + ', ' + p.experienceYears + ' yr, looking for ' + p.goal).join('\n'), 'persona');
} else if (v === 'cpro') {
  say(CAND + ' · Profile\n\n' + P.name + '\nDegree: ' + P.degree + ' (' + P.field + ')\nExperience: ' + P.experienceYears + ' year(s)\n' +
    'Skills: ' + P.skills.join(', ') + '\nCity: ' + P.location + '\nLooking for: ' + P.goal + '\n\n' +
    'Every match score is calculated from this profile. Next: Browse internships to see what is open.', 'cand');
} else if (v === 'cb') {
  const lines = cat.jobs.map((j, i) => (i + 1) + '. ' + j.title + ', ' + first(j.company) + ' (' + j.location + ')' +
    (cat.recruiterPostings.includes(j.id) ? ' [recruiter demo: can apply]' : '') + '\n   Needs: ' + needsLine(j));
  say(CAND + ' · Open internships (' + cat.jobs.length + ', fictional catalogue)\n\n' + lines.join('\n') +
    '\n\nNext: My matches scores ' + first(P.name) + ' against all of these.', 'cand');
} else if (v === 'cm' || v === 'cw') {
  if (!Array.isArray(r.allScored)) engineFailed();
  else if (v === 'cm') {
    const n = r.allScored.length;
    say(CAND + ' · Matches for ' + first(P.name) + '\n' +
      'All ' + cat.jobs.length + ' internships checked: ' + n + ' eligible, ' + r.excluded.length + ' ruled out by the degree rule.\n' +
      'Score = skills 40 + experience 30 + education 30. Top 5:');
    r.allScored.slice(0, 5).forEach((j, i) => {
      const job = jobById[j.id];
      const open = cat.recruiterPostings.includes(j.id);
      const applied = (plan.applications[j.id] || []).includes(P.id);
      say('#' + (i + 1) + '  ' + j.score + '/100  ' + bar(j.score) + '\n' + j.title + '\n' + first(j.company) + ' · ' + j.location + '\n' +
        'Has: ' + (j.matchedSkills.join(', ') || 'none') + '\nMissing: ' + (j.missingSkills.join(', ') || 'none') + '\n' +
        'Experience: ' + P.experienceYears + ' yr of ' + job.minimumExperienceYears + ' required' +
        (open ? (applied ? '\nApplied ✓' : '\nOpen in the recruiter demo: you can apply.') : ''),
        open && !applied ? 'jobApply' : 'job', { jobId: j.id });
    });
    const ex = r.excluded.map(e => '• ' + jobById[e.jobId].title + ': ' + e.reason).join('\n');
    say((ex ? 'Not eligible:\n' + ex + '\n\n' : '') + (r.persistedRows ? 'Top 3 saved to Postgres: ' + r.persistedRows + ' rows upserted, no duplicates' + (r.timesSaved > 1 ? ' (saved ' + r.timesSaved + ' times since ' + new Date(r.firstSaved).toLocaleString('en-GB', { timeZone: 'Europe/Paris', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) + ')' : ' (first save)') + '.\n' : 'Saving was unavailable this time; the scores are unaffected.\n') +
      'Tap "Why this score?" on a card, Apply where it is open, or AI advice for a written summary.', 'cand');
  } else {
    const j = r.allScored.find(x => x.id === plan.arg);
    const job = jobById[plan.arg];
    if (!j) say(CAND + '\n' + (job ? job.title + ' is not eligible for ' + first(P.name) + ' (degree rule).' : 'Unknown internship.'), 'cand');
    else {
      const open = cat.recruiterPostings.includes(j.id) && !(plan.applications[j.id] || []).includes(P.id);
      say(CAND + ' · Why ' + j.title + ' scored ' + j.score + '/100 for ' + first(P.name) + '\n\n' +
        'Eligibility: needs ' + job.minimumEducation + ', has ' + P.degree + ' → eligible\n' +
        'Skills: ' + j.matchedSkills.length + ' of ' + job.requiredSkills.length + ' required' +
        (j.matchedSkills.length ? ' (' + j.matchedSkills.join(', ') + ')' : '') + ' → ' + j.breakdown.skills + '/40\n' +
        'Experience: ' + P.experienceYears + ' of ' + job.minimumExperienceYears + ' yr → ' + j.breakdown.experience + '/30\n' +
        'Education: requirement met → ' + j.breakdown.education + '/30\n' +
        (j.missingSkills.length ? '\nTo improve: learn ' + j.missingSkills.join(', ') + '.\n' : '\n') +
        'Same rules for every internship. The AI never changes scores.', open ? 'whyApply' : 'why', { jobId: j.id });
    }
  }
} else if (v === 'ca') {
  const job = jobById[plan.arg];
  if (plan.error || !job) say(CAND + '\n' + (plan.error || 'Unknown internship.'), 'cand');
  else {
    const total = cat.applicantCounts[job.id] + (plan.applications[job.id] || []).length;
    say(CAND + ' · ' + (plan.alreadyApplied ? 'Already applied' : 'Application sent') + '\n' +
      first(P.name) + ' → ' + job.title + ' at ' + first(job.company) + '.\n' + total + ' applicants now.\n\n' +
      'Switch to the RECRUITER SIDE and open this posting to see where ' + first(P.name) + ' ranks.', 'candAfterApply', { jobId: job.id });
  }
} else if (v === 'ci') {
  const ok = typeof r.message === 'string' && /verified/i.test(String(r.source || ''));
  say(CAND + ' · AI advice for ' + first(P.name) + '\n\n' + (ok ? r.message + '\n\n(Checked: every job title and score above matches the scoring engine.)'
    : 'The AI explanation is unavailable right now (free model limit or a failed check). The scores in My matches still stand.'), 'cand');
} else if (v === 'cl') {
  if (!Array.isArray(r.jobs)) say((plan.drill ? 'FAILURE DRILL (on purpose)\nThe controller sent workflow 09 to a job board that does not exist. The HTTP call was retried 3 times, workflow 09 failed, the error workflow alerted the owner, and this reply came from the error path.\n\n' : '') + CAND + ' · Real market\nThe live public job board is unavailable right now. No listings were invented.', 'cand');
  else {
    say(CAND + ' · Real market (live)\nSource: ' + r.board + ' on Greenhouse, fetched just now.\n' + r.internshipCount + ' real internship listings. ' +
      'Ranked by how many of ' + first(P.name) + '\'s skills the description mentions.\nRequirements are NOT verified, so these get no score.');
    r.jobs.slice(0, 5).forEach((j, i) => say((i + 1) + '. ' + j.title + '\n' + j.location + '\nMentions: ' +
      (j.mentionedSkills.join(', ') || 'none of ' + first(P.name) + '\'s skills') + '\n' + j.url));
    say('Real listings are evidence of the market. The fictional catalogue is where scoring and applying happen.', 'cand');
  }
} else if (v === 'r') {
  say(REC + '\nChoose a job posting to review (fictional employers):\n\n' + cat.recruiterPostings.map(id => {
    const j = jobById[id]; const tg = (plan.applications[id] || []).length;
    return '• ' + j.title + ', ' + first(j.company) + ': ' + cat.applicantCounts[id] + ' applicants' + (tg ? ' + ' + tg + ' via Telegram' : '');
  }).join('\n') + (Object.values(plan.applications).some(l => l.length) ? '\n\n★ = a student who applied through this chat.' : '\n\nTip: no student has applied through this chat yet. On the candidate side, open My matches and tap Apply on an internship marked "you can apply"; the student then appears here with a ★.'), 'postings');
} else if (v === 'rerror') {
  say(REC + '\nSettings not changed. ' + plan.error + '\nExample: /recruiter skills=30 experience=50 education=20 threshold=60', 'rec');
} else if (v === 'rdash' || v === 'rn') {
  if (!Array.isArray(r.allEvaluations)) engineFailed();
  else {
    const job = jobById[plan.postingId];
    const W = plan.settings.weights, T = plan.settings.threshold;
    const cands = plan.engineInput.candidates;
    const names = Object.fromEntries(cands.map(c => [c.id, c.name]));
    const evals = r.allEvaluations;
    const above = evals.filter(c => c.score >= T);
    const top3 = new Set(above.slice(0, 3).map(c => c.id));
    const statusOf = c => top3.has(c.id) ? 'INTERVIEW' : (c.score >= T ? 'ELIGIBLE' : 'NOT_PROGRESSING');
    const label = { INTERVIEW: 'top 3 · interview', ELIGIBLE: 'eligible', NOT_PROGRESSING: 'below threshold', INELIGIBLE: 'ineligible' };
    const settingsLine = 'Weights: skills ' + W.skills + ' / experience ' + W.experience + ' / education ' + W.education + ' · threshold ' + T;
    const star = id => String(id).startsWith('TG-') ? '★ ' : '';
    if (v === 'rdash') {
      const scores = evals.map(c => c.score).sort((a, b) => a - b);
      const avg = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
      const mid = scores.length ? (scores.length % 2 ? scores[(scores.length - 1) / 2] : Math.round((scores[scores.length / 2 - 1] + scores[scores.length / 2]) / 2)) : 0;
      const miss = {}; evals.forEach(c => c.missingSkills.forEach(s => { miss[s] = (miss[s] || 0) + 1; }));
      const topMiss = Object.entries(miss).sort((a, b) => b[1] - a[1])[0];
      const tg = cands.filter(c => c.viaTelegram).length;
      say(REC + ' · ' + job.title + ', ' + first(job.company) + '\n' + (plan.note ? plan.note + '\n' : '') +
        'Requirements: ' + needsLine(job) + ' (degree is a hard rule)\n' + settingsLine + '\n\n' +
        'Applicants ' + cands.length + (tg ? ' (' + tg + ' via Telegram ★)' : '') + ' | ineligible ' + r.excluded.length + ' | scored ' + evals.length + ' | at/above threshold ' + above.length + '\n' +
        'Average ' + avg + ' | median ' + mid + ' | range ' + (scores[0] ?? '-') + '-' + (scores[scores.length - 1] ?? '-') +
        (topMiss ? '\nMost common missing skill: ' + topMiss[0] + ' (' + topMiss[1] + ' of ' + evals.length + ')' : ''));
      const short = n => first(n).replace(/\s*\(.*$/, '');
      const cfg = { type: 'horizontalBar', data: { labels: evals.map((c, i) => (i + 1) + '. ' + star(c.id) + short(c.name) + ' (' + c.score + ')'),
        datasets: [{ label: 'Skills', data: evals.map(c => c.scoreBreakdown.skills), backgroundColor: '#1f6feb' },
          { label: 'Experience', data: evals.map(c => c.scoreBreakdown.experience), backgroundColor: '#0f9d6b' },
          { label: 'Education', data: evals.map(c => c.scoreBreakdown.education), backgroundColor: '#e0a100' }] },
        options: { title: { display: true, text: job.title + ': score per applicant (red line = threshold ' + T + ')' },
          legend: { position: 'bottom' },
          scales: { xAxes: [{ stacked: true, ticks: { min: 0, max: 100, stepSize: 10 } }], yAxes: [{ stacked: true }] },
          annotation: { annotations: [{ type: 'line', mode: 'vertical', scaleID: 'x-axis-0', value: T, borderColor: '#d92d20', borderWidth: 3 }] } } };
      const url = 'https://quickchart.io/chart?w=800&h=' + (140 + 34 * evals.length) + '&bkg=white&c=' + encodeURIComponent(JSON.stringify(cfg));
      msgs.push({ kind: 'photo', kb: 'photo', photoUrl: url, text: 'Each bar = skills + experience + education. ' + (r.excluded.length ? r.excluded.length + ' ineligible applicant(s) are not scored.' : '') });
      const list = evals.map((c, i) => (i + 1) + '. ' + star(c.id) + first(c.name) + ': ' + c.score + ' · ' + label[statusOf(c)] + '\n   ' +
        'skills ' + c.scoreBreakdown.skills + '/' + W.skills + (c.missingSkills.length ? ' (missing ' + c.missingSkills.join(', ') + ')' : '') +
        ' · exp ' + c.scoreBreakdown.experience + '/' + W.experience + ' (' + c.experienceYears + ' yr) · edu ' + c.scoreBreakdown.education + '/' + W.education + ' (' + c.education + ')');
      const inel = r.excluded.map(e => '• ' + first(names[e.id] || e.id) + ': ' + e.reason);
      say('RANKED APPLICANTS\n' + list.join('\n') + (inel.length ? '\n\nINELIGIBLE (not scored)\n' + inel.join('\n') : '') +
        '\n\nChange the weighting with the buttons, then Notify applicants. Scores support a human decision; they never make it.', 'rec');
    } else {
      const prev = (store.notified[plan.postingId] = store.notified[plan.postingId] || {});
      const text = {
        INTERVIEW: 'Good news: you meet the criteria for ' + job.title + ' and are invited to an interview.',
        ELIGIBLE: 'You meet the criteria for ' + job.title + ' and are under consideration.',
        NOT_PROGRESSING: 'Thank you for applying for ' + job.title + '. Under the current criteria we will not progress your application.',
        INELIGIBLE: 'Thank you for applying for ' + job.title + '. It requires a ' + job.minimumEducation + ' degree or higher, so you are not eligible.' };
      const all = evals.map(c => ({ id: c.id, name: c.name, score: c.score, status: statusOf(c), missing: c.missingSkills }))
        .concat(r.excluded.map(e => ({ id: e.id, name: names[e.id] || e.id, score: null, status: 'INELIGIBLE', missing: [] })));
      const out = []; let same = 0;
      for (const c of all) {
        if (prev[c.id] === c.status) { same++; continue; }
        const upd = !!prev[c.id];
        let body = (upd ? 'Update: the recruiter changed the selection criteria. ' : '') + text[c.status];
        if (c.status === 'NOT_PROGRESSING' && c.missing.length) body += ' Adding ' + c.missing.join(', ') + ' would strengthen a future application.';
        out.push((upd ? 'UPDATE (was ' + label[prev[c.id]] + ')' : 'NEW') + ' → ' + star(c.id) + first(c.name) + (c.score === null ? '' : ' (' + c.score + ')') + ': ' + label[c.status] +
          '\n   "Hello ' + first(c.name).split(' ')[0] + '. ' + body + '"');
        prev[c.id] = c.status;
      }
      say(REC + ' · Notifications for ' + job.title + '\n' + settingsLine + '\n\n' +
        (out.length ? out.join('\n') : 'No applicant\'s status changed since the last notification, so nobody is messaged.') +
        '\n\n' + out.length + ' message(s) queued, ' + same + ' unchanged. Outbox is simulated (fictional applicants); in production a recruiter approves before email is sent.', 'rec');
    }
  }
}
